mapper.update:
update ai_invite_affiliate
set invite_count = invite_count + 1, update_time = sysdate()
where user_id = #{inviterId}

update ai_invite_affiliate
set rebate_rate = #{rebateRate}, update_time = sysdate()
where user_id = #{userId}

update ai_invite_affiliate
set invite_code = #{inviteCode}, update_time = sysdate()
where user_id = #{userId}

mapper.select:
select a.user_id, u.user_name, a.invite_code, a.inviter_id, inviter.user_name as inviter_user_name, a.invite_count, a.pending_rebate, a.frozen_rebate, a.history_rebate, a.rebate_rate, a.create_by, a.create_time, a.update_by, a.update_time, a.remark from ai_invite_affiliate a left join sys_user u on u.user_id = a.user_id left join sys_user inviter on inviter.user_id = a.inviter_id
and a.invite_code like concat('%', #{inviteCode}, '%') and a.inviter_id = #{inviterId}
order by a.user_id desc
